INSERT INTO `galaxy_proxy` VALUES (1, 'map', '/traffic/map', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT server_country AS server_country,client_country AS client_country,<#if parameter.country?default(\'\')?trim? length gt 0> server_region AS server_region,client_region AS client_region,</#if> SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes,SUM(common_sessions) as sessions FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} <#if parameter.country?default(\'\')?trim? length gt 0> and (server_country = \'${parameter.country}\' AND client_country = \'${parameter.country}\') AND server_region != \'\' AND client_region != \'\'<#else> AND server_country != \'\' AND client_country != \'\'</#if> GROUP BY server_country,client_country <#if parameter.country?default(\'\')?trim? length gt 0>,server_region,client_region</#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100)', 'var countryCodeMap = {\"Private IP\":\"CN\",\"Afghanistan\":\"AF\",\"Albania\":\"AL\",\"Algeria\":\"DZ\",\"American Samoa\":\"AS\",\"Andorra\":\"AD\",\"Angola\":\"AO\",\"Anguilla\":\"AI\",\"Antarctica\":\"AQ\",\"Antigua and Barbuda\":\"AG\",\"Argentina\":\"AR\",\"Armenia\":\"AM\",\"Aruba\":\"AW\",\"Australia\":\"AU\",\"Austria\":\"AT\",\"Azerbaijan\":\"AZ\",\"Bahamas (the)\":\"BS\",\"Bahrain\":\"BH\",\"Bangladesh\":\"BD\",\"Barbados\":\"BB\",\"Belarus\":\"BY\",\"Belgium\":\"BE\",\"Belize\":\"BZ\",\"Benin\":\"BJ\",\"Bermuda\":\"BM\",\"Åland Islands\":\"AX\",\"Bhutan\":\"BT\",\"Bolivia (Plurinational State of)\":\"BO\",\"Bonaire, Sint Eustatius and Saba\":\"BQ\",\"Bosnia and Herzegovina\":\"BA\",\"Botswana\":\"BW\",\"Bouvet Isl