\":\"PL-22\",\"Slaskie\":\"PL-24\",\"Swietokrzyskie\":\"PL-26\",\"Warminsko-mazurskie\":\"PL-28\",\"Wielkopolskie\":\"PL-30\",\"Zachodniopomorskie\":\"PL-32\"},\"PM\":{\"Saint Pierre and Miquelon\":\"\"},\"PN\":{\"Pitcairn\":\"\"}};\r\n\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj= {};\r\n			\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			\r\n			tempObj.serverId = countryCodeMap[tempObj.serverCountry];\r\n			tempObj.clientId = countryCodeMap[tempObj.clientCountry];\r\n			\r\n			if(tempObj.serverId == undefined) {\r\n				tempObj.serverId = \"\";\r\n			}else{\r\n				// 存在地区 \r\n				if(tempObj.serverRegion != undefined){\r\n					var regionCode = countCityMap[tempObj.serverId][tempObj.serverRegion];\r\n					if(regionCode != undefined){\r\n						tempObj.serverId = regionCode;\r\n					}\r\n				}\r\n			}\r\n			\r\n			if(tempObj.clientId == undefined) {\r\n				tempObj.clientId = \"\";\r\n			}else{\r\n				// 存在地区 \r\n				if(tempObj.clientRegion != undefined){\r\n					var regionCode = countCityMap[tempObj.clientId][tempObj.clientRegion];\r\n					if(regionCode != undefined){\r\n						tempObj.clientId = regionCode;\r\n					}\r\n				}\r\n			}\r\n			\r\n			\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-06-08 13:43:32', '2021-06-08 13:43:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (2, 'sessions', '/traffic/sessions', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') AS stat_time, ROUND(SUM(common_sessions)/${parameter.step*60}) AS session_rate FROM tsg_base_metrics WHERE common_recv_time>=${parameter.startTime} AND common_recv_time<${parameter.endTime} GROUP BY stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"stat_time\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-06-08 13:43:32', '2021-06-08 13:43:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (3, 'packets', '/traffic/packets', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT     TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') AS stat_time,     ROUND(SUM(common_s2c_pkt_num)/${parameter.step*60}) AS packets_received_rate,     ROUND(SUM(common_c2s_pkt_num)/${parameter.step*60}) AS packets_sent_rate,     ROUND(SUM(common_c2s_pkt_num + common_s2c_pkt_num)/${parameter.step*60}) AS packets_rate FROM     tsg_base_metrics WHERE     common_recv_time >=${parameter.startTime}     AND common_recv_time < ${parameter.endTime} GROUP BY     stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"stat_time\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-06-11 15:52:13', '2021-06-11 15:52:15', 1, '');
INSERT INTO `galaxy_proxy` VALUES (4, 'throughput', '/traffic/throughput', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT     TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') AS stat_time,     ROUND(SUM(common_c2s_byte_num)/${parameter.step*60}) AS bytes_sent_rate,     ROUND(SUM(common_s2c_byte_num)/${parameter.step*60}) AS bytes_received_rate,     ROUND(SUM(common_c2s_byte_num + common_s2c_byte_num)/${parameter.step*60}) AS bytes_rate FROM     tsg_base_metrics WHERE     common_recv_time >= ${parameter.startTime}     AND common_recv_time < ${parameter.endTime} GROUP BY     stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"stat_time\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-06-11 16:04:34', '2021-06-11 16:04:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (5, 'activeClientIP', '/traffic/activeClientIP', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT          common_client_ip                               AS client_ip        , SUM(common_sessions)                        as sessions        , SUM(common_c2s_pkt_num  + common_s2c_pkt_num)  as packets        , SUM(common_c2s_byte_num + common_s2c_byte_num) as bytes FROM          tsg_base_metrics WHERE          common_recv_time    >= ${parameter.startTime}          AND common_recv_time < ${parameter.endTime} GROUP BY          client_ip ORDER BY          ${parameter.order} desc limit ${parameter.limit}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100)', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj= {};\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-06-11 16:08:19', '2021-06-11 16:08:21', 1, '');
INSERT INTO `galaxy_proxy` VALUES (6, 'activeServerIP', '/traffic/activeServerIP', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT          common_server_ip                               AS server_ip        , SUM(common_sessions)                        AS sessions        , SUM(common_c2s_pkt_num  + common_s2c_pkt_num)  as packets        , SUM(common_c2s_byte_num + common_s2c_byte_num) as bytes FROM          tsg_base_metrics WHERE          common_recv_time    >= ${parameter.startTime}          AND common_recv_time < ${parameter.endTime} GROUP BY          server_ip ORDER BY          ${parameter.order} desc limit ${parameter.limit}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100)', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj= {};\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-06-11 16:15:56', '2021-06-11 16:16:02', 1, '');
INSERT INTO `galaxy_proxy` VALUES (7, 'topDomains', '/traffic/topDomains', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT          domain                                         AS domain        , SUM(common_sessions)                        AS sessions        , SUM(common_c2s_pkt_num  + common_s2c_pkt_num)  as packets        , SUM(common_c2s_byte_num + common_s2c_byte_num) as bytes FROM          tsg_base_metrics WHERE          common_recv_time    >= ${parameter.startTime}          AND common_recv_time < ${parameter.endTime}          AND notEmpty(domain) GROUP BY          domain ORDER BY          ${parameter.order} desc limit ${parameter.limit}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100)', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj= {};\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-06-11 16:18:45', '2021-06-11 16:18:47', 1, '');
INSERT INTO `galaxy_proxy` VALUES (8, 'toApp', '/traffic/topApp', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT     common_app_label AS app_label,  SUM(common_sessions) as sessions,     SUM(common_c2s_pkt_num + common_s2c_pkt_num) as packets,     SUM(common_c2s_byte_num + common_s2c_byte_num) as bytes FROM     tsg_base_metrics WHERE     common_recv_time >= ${parameter.startTime}     AND common_recv_time < ${parameter.endTime}     AND notEmpty(common_app_label) GROUP BY  common_app_label ORDER BY     ${parameter.order} desc limit ${parameter.limit}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100)', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj= {};\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-06-11 16:22:33', '2021-06-11 16:22:35', 1, '');
INSERT INTO `galaxy_proxy` VALUES (9, 'topDomainCategories', '/traffic/topDomainCategories', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT     fqdn_category_name as fqdn_category_name,     uniq(domain) AS uniq_domains,     SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes,     SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets,     SUM(common_sessions) AS sessions FROM     tsg_base_metrics WHERE     common_recv_time >= ${parameter.startTime}     AND common_recv_time < ${parameter.endTime}     AND notEmpty(domain)     AND notEmpty(fqdn_category_name) GROUP BY     fqdn_category_name ORDER BY     uniq_domains DESC limit ${parameter.limit}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100)', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj= {};\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-06-11 16:37:03', '2021-06-11 16:37:05', 1, '');
INSERT INTO `galaxy_proxy` VALUES (10, 'activeDomainCategories', '/traffic/activeDomainCategories', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT domain AS domain,anyLast(fqdn_category_name) as category_name, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes, SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets, SUM(common_sessions) AS sessions FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND notEmpty(domain) <#if parameter.fqdnCategoryName?default(\'\')?trim? length gt 0> AND fqdn_category_name in (<#list parameter.fqdnCategoryName?split(\",\") as name><#if !name_has_next>\'${name}\'<#else>\'${name}\',</#if></#list>) </#if>  GROUP BY domain ORDER BY <#if parameter.order?default(\'\')?trim?length gt 0> ${parameter.order} <#else> sessions </#if> DESC limit ${parameter.limit}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100)', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj= {};\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-06-11 16:41:37', '2021-06-11 16:41:41', 1, '');
INSERT INTO `galaxy_proxy` VALUES (11, 'topDomainReputation', '/traffic/topDomainReputation', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT     fqdn_reputation_level as fqdn_reputation_level,     uniq(domain) AS uniq_domains,     SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes,     SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets,     SUM(common_sessions) AS sessions FROM     tsg_base_metrics WHERE     common_recv_time >= ${parameter.startTime}     AND common_recv_time < ${parameter.endTime}     AND notEmpty(domain)     AND notEmpty(fqdn_reputation_level) GROUP BY     fqdn_reputation_level ORDER BY     uniq_domains DESC limit ${parameter.limit}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100)', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj= {};\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-06-11 16:48:21', '2021-06-11 16:48:23', 1, '');
INSERT INTO `galaxy_proxy` VALUES (12, 'activeDomainReputation', '/traffic/activeDomainReputation', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT domain AS domain,anyLast(fqdn_reputation_level) AS reputation_level,SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes,     SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets,SUM(common_sessions) AS sessions FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND notEmpty(domain) <#if parameter.fqdnReputationLevel?default(\'\')?trim? length gt 0> AND fqdn_reputation_level in (<#list parameter.fqdnReputationLevel?split(\",\") as level><#if !level_has_next>\'${level}\'<#else>\'${level}\',</#if></#list>) </#if> GROUP BY domain ORDER BY <#if parameter.order?default(\'\')?trim? length gt 0 > ${parameter.order} <#else> sessions </#if> DESC limit ${parameter.limit}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100)', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj= {};\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-06-11 16:50:08', '2021-06-11 16:50:10', 1, '');
INSERT INTO `galaxy_proxy` VALUES (13, 'rtt', '/npm/rtt', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT ROUND(AVG(common_establish_latency_ms)) AS establish_latency FROM tsg_base_metrics WHERE  common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_l4_protocol IN (\'IPv4_TCP\',\'IPv6_TCP\')\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-06-23 18:02:32', '2021-06-23 18:02:34', 1, '');
INSERT INTO `galaxy_proxy` VALUES (14, 'httpResponseTime', '/npm/httpResponseTime', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT ROUND(AVG(http_response_latency_ms)) AS http_response_latency FROM tsg_base_metrics   WHERE common_recv_time>=${parameter.startTime} AND common_recv_time<${parameter.endTime} AND common_schema_type = \'HTTP\'\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-06-23 18:04:55', '2021-06-23 18:04:57', 1, '');
INSERT INTO `galaxy_proxy` VALUES (15, 'sslHandshakeTime', '/npm/sslHandshakeTime', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT ROUND(AVG(ssl_con_latency_ms)) AS ssl_con_latency FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_schema_type = \'SSL\'\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-06-23 18:06:47', '2021-06-23 18:06:49', 1, '');
INSERT INTO `galaxy_proxy` VALUES (16, 'avgPacketLossRate', '/npm/avgPacketLossRate', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT ROUND(SUM(common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/SUM(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen),4) AS sequence_gap_loss_percent FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_l4_protocol IN (\'IPv4_TCP\',\'IPv6_TCP\')\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 10 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-06-23 18:07:19', '2021-06-23 18:07:21', 1, '');
INSERT INTO `galaxy_proxy` VALUES (17, 'avgRetransmissionRate', '/npm/avgRetransmissionRate', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT ROUND(SUM(common_c2s_pkt_retrans + common_s2c_pkt_retrans)/  SUM(common_c2s_pkt_num + common_s2c_pkt_num),4) AS pkt_retrans_percent FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_l4_protocol IN (\'IPv4_TCP\',\'IPv6_TCP\')\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 10 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-06-23 18:08:36', '2021-06-23 18:08:38', 1, '');
INSERT INTO `galaxy_proxy` VALUES (18, 'rttMap', '/npm/rttMap', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT ROUND(AVG(common_establish_latency_ms)) AS establish_latency,<#if parameter.country?default(\'\')?trim? length gt 0> server_region AS server_region <#else> server_country AS server_country </#if> FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_l4_protocol IN (\'IPv4_TCP\',\'IPv6_TCP\') <#if parameter.country?default(\'\')?trim? length gt 0> AND server_region != \'\' AND server_country in (\'${parameter.country}\') <#else> AND server_country != \'\' </#if> GROUP BY <#if parameter.country?default(\'\')?trim? length gt 0> server_region <#else> server_country </#if> ORDER BY establish_latency DESC\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100)', '\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n\r\n\r\nvar countryCodeMap = {\"Afghanistan\":\"AF\",\"Albania\":\"AL\",\"Algeria\":\"DZ\",\"American Samoa\":\"AS\",\"Andorra\":\"AD\",\"Angola\":\"AO\",\"Anguilla\":\"AI\",\"Antarctica\":\"AQ\",\"Antigua and Barbuda\":\"AG\",\"Argentina\":\"AR\",\"Armenia\":\"AM\",\"Aruba\":\"AW\",\"Australia\":\"AU\",\"Austria\":\"AT\",\"Azerbaijan\":\"AZ\",\"Bahamas (the)\":\"BS\",\"Bahrain\":\"BH\",\"Bangladesh\":\"BD\",\"Barbados\":\"BB\",\"Belarus\":\"BY\",\"Belgium\":\"BE\",\"Belize\":\"BZ\",\"Benin\":\"BJ\",\"Bermuda\":\"BM\",\"Åland Islands\":\"AX\",\"Bhutan\":\"BT\",\"Bolivia (Plurinational State of)\":\"BO\",\"Bonaire, Sint Eustatius and Saba\":\"BQ\",\"Bosnia and Herzegovina\":\"BA\",\"B