INSERT INTO `galaxy_proxy` VALUES (25, 'domainFilter', '/entity/domain/filter', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT <#if parameter.type?default(\'\')?trim? length gt 0&&parameter.type==\'categoryGroup\'>category_group AS category_group,<#elseif parameter.type?default(\'\')?trim? length gt 0&&parameter.type==\'categoryName\'>category_name AS category_name,<#else>reputation_level AS reputation_level,</#if> count(*) AS count FROM domain WHERE 1=1 <#if parameter.type?default(\'\')?trim? length gt 0&&parameter.type==\'categoryGroup\'>and category_group!=\'\'<#elseif parameter.type?default(\'\')?trim? length gt 0&&parameter.type==\'categoryName\'>and category_name != \'\'<#else>and reputation_level != \'\'</#if> <#if parameter.categoryGroup?default(\'\')?trim? length gt 0 > and category_group = \'${parameter.categoryGroup}\' </#if> <#if parameter.categoryName?default(\'\')?trim? length gt 0 > and category_name = \'${parameter.categoryName}\'</#if><#if parameter.reputationLevel?default(\'\')?trim? length gt 0> AND reputation_level in (<#list parameter.reputationLevel?split(\",\") as reputationLevel><#if !reputationLevel_has_next>\'${reputationLevel}\'<#else>\'${reputationLevel}\',</#if></#list>) </#if><#if parameter.domain?default(\'\')?trim? length gt 0 > and domain_name = \'${parameter.domain}\'</#if> GROUP BY <#if parameter.type?default(\'\')?trim? length gt 0&&parameter.type==\'categoryGroup\'>category_group<#elseif parameter.type?default(\'\')?trim? length gt 0&&parameter.type==\'categoryName\'>category_name<#else>reputation_level</#if> ORDER BY count DESC <#if parameter.pageSize?default(\'\')?trim? length gt 0>limit ${parameter.pageNo},${parameter.pageSize}</#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (parameter.pageSize) {\r\n	if(!parameter.pageNo){\r\n		parameter.pageNo=0\r\n	}else{\r\n		parameter.pageNo=(parameter.pageNo-1)*parameter.pageSize\r\n	}\r\n}', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj= {};\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-06-29 15:39:15', '2021-06-29 15:39:17', 1, '');
