		var aggregation = {};\r\n			aggregation.first = list[0][valueName];\r\n			aggregation.last = list[list.length - 1][valueName];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[valueName]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[valueName]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[valueName]-a[valueName];\r\n			});\r\n			aggregation.max = list[0][valueName];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-07-01 09:48:59', '2021-07-01 09:49:01', 1, '');
