INSERT INTO `galaxy_proxy` VALUES (117, 'ipDetailAsn', '/entity/ip/detail/asn', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT <#if parameter.serverIP?default(\'\')?trim? length gt 0> server_asn <#else> client_asn </#if> AS asn FROM tsg_base_metrics WHERE <#if parameter.serverIP?default(\'\')?trim? length gt 0> common_server_ip = \'${parameter.serverIP}\' <#else> common_client_ip = \'${parameter.clientIP}\' </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', '', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-07-20 13:42:12', '2021-07-20 13:42:16', 1, '');
INSERT INTO `galaxy_proxy` VALUES (118, 'ipDetailCountry', '/entity/ip/detail/country', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT <#if parameter.serverIP?default(\'\')?trim? length gt 0> server_country <#else> client_country </#if> AS country FROM tsg_base_metrics WHERE <#if parameter.serverIP?default(\'\')?trim? length gt 0> common_server_ip = \'${parameter.serverIP}\' <#else> common_client_ip = \'${parameter.clientIP}\' </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', '', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-07-20 13:42:12', '2021-07-20 13:42:16', 1, '');
INSERT INTO `galaxy_proxy` VALUES (119, 'ipDetailTrafficMap', '/entity/ip/detail/trafficMap', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT     server_country AS server_country,     client_country AS client_country, 	<#if parameter.country?default(\'\')?trim? length gt 0> 		server_region AS server_region, 		client_region AS client_region, 	</#if>     SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes,     SUM(common_sessions) as sessions FROM     tsg_base_metrics WHERE     common_recv_time >= ${parameter.startTime}     AND common_recv_time < ${parameter.endTime} 	AND  <#if parameter.serverIP?default(\'\')?trim? length gt 0> common_server_ip = \'${parameter.serverIP}\' <#else> common_client_ip = \'${parameter.clientIP}\' </#if>  	<#if parameter.country?default(\'\')?trim? length gt 0> 	    AND server_region != \'\' 		AND client_region != \'\' 		AND server_country = \'${parameter.country}\' 		AND client_country = \'${parameter.country}\' 	<#else> 		AND server_country != \'\' 		AND client_country != \'\' 	</#if> GROUP BY     <#if parameter.country?default(\'\')?trim? length gt 0> 		server_country, 		client_country, 		server_region, 		client_region 	<#else> 		server_country, 		client_country 	</#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', '\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n\r\n\r\nvar countryCodeMap = {\"Afghanistan\":\"AF\",\"Albania\":\"AL\",\"Algeria\":\"DZ\",\"American Samoa\":\"AS\",\"Andor