tion.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-07-01 09:48:59', '2021-07-01 09:49:01', 1, '');
INSERT INTO `galaxy_proxy` VALUES (146, 'entityList', '/entity/list', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT <#if parameter.from?default(\'\')?trim? length gt 0&&parameter.from==\'ip\'> ip_addr AS ip, locate_country AS country, locate_region AS region, asn AS asn <#elseif parameter.from?default(\'\')?trim? length gt 0&&parameter.from==\'domain\'> domain_name AS domain_name, category_group AS category_group, category_name AS category_name, reputation_level AS reputation_level, reputation_score AS reputation_score <#else> app_id AS app_id, app_name AS app_name, app_category AS app_category, app_subcategory AS app_subcategory, app_risk AS app_risk </#if> FROM <#if parameter.from?default(\'\')?trim? length gt 0&&parameter.from==\'ip\'> ip <#elseif parameter.from?default(\'\')?trim? length gt 0&&parameter.from==\'domain\'> domain <#else> app </#if> WHERE 1=1 <#if parameter.q?default(\'\')?trim? length gt 0>and ${parameter.q} </#if> ORDER BY update_time DESC <#if parameter.pageSize?default(\'\')?trim? length gt 0>limit ${parameter.pageNo},${parameter.pageSize}</#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (parameter.pageSize) {\r\n	if(!parameter.pageNo){\r\n		parameter.pageNo=0\r\n	}else{\r\n		parameter.pageNo=(parameter.pageNo-1)*parameter.pageSize\r\n	}\r\n}\r\nif(parameter.q){\r\n       var q = parameter.q\r\n       var arr=[]\r\n       q = q.replace(/Unknown/ig,\"\")\r\n       if(q.match(/ip_addr/ig)){\r\n           arr = q.split(/ip_addr/i)\r\n           var index1 = arr[1].indexOf(\"\'\")\r\n           var index = arr[1].slice(index1+1).indexOf(\"\'\")\r\n           arr[1] = arr[1].slice(0,(index1+index+1))+\"%\"+arr[1].slice((index1+index+1))\r\n           arr[1] = arr[1].replace(\"=\",\" like\")\r\n           q = arr.join(\"ip_addr\")\r\n       }\r\n       if(q.match(/domain_name/ig)){\r\n           arr = q.split(/domain_name/i)\r\n           var index1 = arr[1].indexOf(\"\'\")\r\n           var index = arr[1].slice(index1+1).indexOf(\"\'\")\r\n           arr[1] = arr[1].slice(0,(index1+index+1))+\"%\"+arr[1].slice((index1+index+1))\r\n           arr[1] = arr[1].replace(\"=\",\" like\")\r\n           q = arr.join(\"domain_name\")\r\n       }\r\n        if(q.match(/app_name/ig)){\r\n           arr = q.split(/app_name/i)\r\n           var index1 = arr[1].indexOf(\"\'\")\r\n           var index = arr[1].slice(index1+1).indexOf(\"\'\")\r\n           arr[1] = arr[1].slice(0,(index1+index+1))+\"%\"+arr[1].slice((index1+index+1))\r\n           arr[1] = arr[1].replace(\"=\",\" like\")\r\n           q = arr.join(\"app_name\")\r\n       }\r\n       parameter.q = q\r\n}', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n                        var pojo = o.result[i];\r\n			var tempObj= {};\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-07-27 16:38:54', '2021-07-27 16:38:59', 1, '');
INSERT INTO `galaxy_proxy` VALUES (147, 'entityTotal', '/entity/total', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT count(*) AS count FROM <#if parameter.from?default(\'\')?trim? length gt 0&&parameter.from==\'ip\'> ip <#elseif parameter.from?default(\'\')?trim? length gt 0&&parameter.from==\'domain\'> domain <#else> app </#if>  WHERE 1=1 <#if parameter.q?default(\'\')?trim? length gt 0>and ${parameter.q} </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if(parameter.q){\r\n       var q = parameter.q\r\n       var arr=[]\r\n       q = q.replace(/Unknown/ig,\"\")\r\n       if(q.match(/ip_addr/ig)){\r\n           arr = q.split(/ip_addr/i)\r\n           var index1 = arr[1].indexOf(\"\'\")\r\n           var index = arr[1].slice(index1+1).indexOf(\"\'\")\r\n           arr[1] = arr[1].slice(0,(index1+index+1))+\"%\"+arr[1].slice((index1+index+1))\r\n           arr[1] = arr[1].replace(\"=\",\" like\")\r\n           q = arr.join(\"ip_addr\")\r\n       }\r\n       if(q.match(/domain_name/ig)){\r\n           arr = q.split(/domain_name/i)\r\n           var index1 = arr[1].indexOf(\"\'\")\r\n           var index = arr[1].slice(index1+1).indexOf(\"\'\")\r\n           arr[1] = arr[1].slice(0,(index1+index+1))+\"%\"+arr[1].slice((index1+index+1))\r\n           arr[1] = arr[1].replace(\"=\",\" like\")\r\n           q = arr.join(\"domain_name\")\r\n       }\r\n        if(q.match(/app_name/ig)){\r\n           arr = q.split(/app_name/i)\r\n           var index1 = arr[1].indexOf(\"\'\")\r\n           var index = arr[1].slice(index1+1).indexOf(\"\'\")\r\n           arr[1] = arr[1].slice(0,(index1+index+1))+\"%\"+arr[1].slice((index1+index+1))\r\n           arr[1] = arr[1].replace(\"=\",\" like\")\r\n           q = arr.join(\"app_name\")\r\n       }\r\n       parameter.q = q\r\n}', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-07-27 16:39:23', '2021-07-27 16:39:26', 1, '');
INSERT INTO `galaxy_proxy` VALUES (148, 'entityIpDetailServerIPCountLine', '/entity/ip/detail/serverIPCountLine', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') as stat_time,<#if parameter.serverIP?default(\'\')?trim? length gt 0> count(distinct(common_server_ip)) AS server_ip_count <#else> count(distinct(common_client_ip)) as client_ip_count</#if> FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND     common_recv_time  < ${parameter.endTime} AND <#if parameter.serverIP?default(\'\')?trim? length gt 0> common_server_ip = \'${parameter.serverIP}\' <#else> common_client_ip = \'${parameter.clientIP}\' </#if> GROUP BY stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', ' if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	\r\n	if(list.length > 0){\r\n		var fields={};\r\n		var field = \"ip\";\r\n		var valueName=\"server_ip_count\";\r\n		for(var i=0;i<list.length;i++){\r\n			var value = fields[list[i][field]];\r\n			var values;\r\n			if(value){\r\n				values = fields[list[i][field]];\r\n				values.push(list[i]);\r\n			}else{\r\n				values = new Array();\r\n				values.push(list[i]);\r\n				fields[list[i][field]]=values;\r\n			}\r\n		}\r\n\r\n		for(var key in fields){\r\n			var list = fields[key];\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][valueName];\r\n			aggregation.last = list[list.length - 1][valueName];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[valueName]));\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[valueName]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[valueName]-a[valueName];\r\n			});\r\n			aggregation.max = list[0][valueName];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-08-13 18:27:25', '2021-08-13 18:27:28', 1, '');
INSERT INTO `galaxy_proxy` VALUES (149, 'entityIpDetailServerIPCount', '/entity/ip/detail/serverIPCount', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT <#if parameter.serverIP?default(\'\')?trim? length gt 0> count(distinct(common_server_ip)) AS server_ip_count <#else> count(distinct(common_client_ip)) as client_ip_count</#if> FROM tsg_base_metrics WHERE <#if parameter.serverIP?default(\'\')?trim? length gt 0> common_server_ip = \'${parameter.serverIP}\' <#else> common_client_ip = \'${parameter.clientIP}\' </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', ' ', ' function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-08-13 18:28:49', '2021-08-13 18:28:51', 1, '');
INSERT INTO `galaxy_proxy` VALUES (150, 'entityRelationship', '/entity/relationship', 'v1', 'POST', '/cn/v1/entityExplorer', '{\"query\": {\"dataEngine\": \"AnalysisEngine\",\"queryType\": \"entityDetail\",\"dataSource\": \"entity_detail_<#if parameter.type==\'serverIP\'>server_ip<#elseif parameter.type==\'clientIP\'>client_ip<#elseif parameter.type==\'app\'>app_id<#else>domain</#if>_view\",\"parameters\": {\"limit\": <#if parameter.limit?default(\'\')?trim? length gt 0>${parameter.limit}<#else>10</#if>,\"sort\": [{\"type\": \"desc\",\"fieldKey\": \"last_time\"}],\"match\": {\"condition\": [{\"type\": \"exactly\",\"fieldKey\": \"<#if parameter.type==\'serverIP\'>server_ip<#elseif parameter.type==\'clientIP\'>client_ip<#elseif parameter.type==\'app\'>app_id<#else>domain</#if>\",\"fieldValues\": [\"${parameter.q?js_string}\"]}]}}}}', '{}', '', 'function handlerResult(obj,data){\r\n	if(data!=null&&data!=undefined){\r\n        if(data.leaf!=null&&data.leaf!=undefined&&data.leaf.length>0){\r\n            for(var i in data.leaf){\r\n                handlerResult(obj,data.leaf[i]);\r\n            }\r\n        }else{\r\n            var node = {};\r\n            node.name = data.name;\r\n            node.type = data.type;\r\n            node.lastTime = data.last_time;\r\n\r\n            var link = {};\r\n            link.from = data.from;\r\n            link.to = data.to;\r\n\r\n            obj.result.links.push(link);\r\n            obj.result.nodes.push(node);\r\n        }\r\n    }\r\n}\r\n\r\nif(result.success){\r\n	if(parameter.format==1){\r\n		var o={};\r\n		o.resultType=\"relation\";\r\n		o.result={};\r\n		o.result.nodes=[];\r\n		o.result.links=[];\r\n		if(result.data!=undefined&&result.data!=null&&result.data.length>0){\r\n			handlerResult(o,result.data[0]);\r\n		}\r\n		result.data=o;\r\n		result.code=200;\r\n		result.msg = \"\";\r\n		result.message=null;\r\n		var jsonObj = {};\r\n		for(var name in result){       \r\n			jsonObj[name] = result[name];\r\n		}\r\n		result = JSON.stringify(jsonObj);\r\n	}else{\r\n		var o={};\r\n		if(result.data!=undefined&&result.data!=null&&result.data.length>0){\r\n			o.resultType=\"relationTree\";\r\n			o.result={};\r\n			o.result.type=result.data[0].type;\r\n			o.result.name=result.data[0].name;\r\n			o.result.leaf=result.data[0].leaf;\r\n		}\r\n		result.data=o;\r\n		result.code=200;\r\n		result.msg = \"\";\r\n		result.message=null;\r\n	}\r\n}', '2021-08-16 09:59:42', '2021-08-16 09:59:45', 1, '');
